      if (failure === 'head') f.state.pr.head.sha = 'd'.repeat(40);
      if (failure === 'base') f.state.pr.base.sha = 'd'.repeat(40);
      if (failure === 'purpose') f.state.comments[0].body += '\nChanged purpose';
      if (failure === 'record') {
